query.sparql:
PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?uri WHERE { res:Salt_Lake_City dbp:location?uri }

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
SELECT DISTINCT?uri WHERE {?uri dct:subject dbc:Assassins_of_Julius_Caesar }

PREFIX dbpedia2: <http://dbpedia.org/property/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?string WHERE { res:Frank_Herbert dbpedia2:birthplace?string }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?string WHERE { res:Angela_Merkel dbp:birthDate?string }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE { res:Berlin dbo:mayor?uri }

SELECT DISTINCT?uri WHERE {
 ?uri a <http://dbpedia.org/ontology/Country>.
 ?uri <http://dbpedia.org/ontology/currency> <http://dbpedia.org/resource/Euro>.
} UNION {
 ?uri <http://dbpedia.org/property/currencyCode> "EUR"@en.
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT?country
WHERE {
  { dbr:Bill_Gates dbo:birthPlace?birthPlace.
   ?birthPlace dbo:location?country.
    FILTER (str(?country) = "United_States") }
  UNION
  { dbr:Bill_Gates dbo:birthPlace?birthPlace.
   ?birthPlace dbo:country?country }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri
WHERE {
 ?uri dbo:occupation "Skateboarding".
 ?uri dbo:birthPlace dbr:Sweden
}
UNION
{
 ?uri dbo:birthPlace?place.
 ?place dbo:country dbr:Sweden
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX yago: <http://dbpedia.org/class/yago/>
PREFIX res: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT?uri WHERE {
 ?uri rdf:type yago:WikicatMonarchsOfTheUnitedKingdom ;
       dbo:spouse?spouse.
 ?spouse dbo:birthPlace yago:Germany.
}

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?String WHERE { res:Millipede dbp:class?String }

PREFIX dbpedia: <http://dbpedia.org/resource/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT DISTINCT?string WHERE { dbpedia:Forbes foaf:homepage?string }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT?uri WHERE { res:Vincent_van_Gogh dbo:publisher?uri }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE { res:K2 dbo:highest?uri }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?date WHERE { res:Finland dbp:membership_date?date }

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT?nm WHERE { dbr:Baghdad rdfs:label?nm }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?string WHERE { res:Berlin dbo:postalCode?string. FILTER (lang(?string) = "en") }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE {
  {?uri dbo:occupation res:Surfer ; dbo:birthPlace res:Australia. }
  UNION
  {?uri dbo:occupation res:Surfer ; dbo:birthPlace?place.?place dbo:location dbr:Australia }
}

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT xsd:date(?date) WHERE { res:Carlo_Giuliani dbp:deathDate?date }

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX onto: <http://dbpedia.org/ontology/>
SELECT?uri?string WHERE { dbr:Abraham_Lincoln onto:spouse?uri }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT?s WHERE {
 ?s dct:subject dbc:Missions_to_the_Sun ;
    rdf:type dbo:Spacecraft
}

SELECT DISTINCT?uri WHERE {
 ?uri a <http://dbpedia.org/ontology/City>.
 ?uri <http://dbpedia.org/ontology/country> <http://dbpedia.org/resource/Germany>.
 ?uri <http://dbpedia.org/ontology/populationTotal>?population.
  FILTER (?population > 250000 )
}

PREFIX res: <http://dbpedia.org/resource/>
PREFIX onto: <http://dbpedia.org/ontology/>
SELECT?number WHERE { res:IBM onto:revenue?number. }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT?uri WHERE {?uri rdfs:label?label. FILTER (LANG(?label) = "en" && STRSTARTS(STR(?label), "http://en.wikipedia.org/wiki/") && STRENDS(STR(?label), "_(first_marriage)") || STRENDS(STR(?label), "_(second_marriage)") ) }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?uri WHERE { res:Yenisei_River dbp:flowsThrough?uri }

SELECT DISTINCT?uri WHERE {{
 ?uri a <http://dbpedia.org/ontology/Astronaut> ;
    <http://dbpedia.org/ontology/nationality> <http://dbpedia.org/resource/China>.
}}

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT DISTINCT?uri WHERE {?uri a dbo:Chancellor_of_Germany. FILTER (lang(?uri) = "en" && strstarts(STR(?uri), "http://dbpedia.org/resource/").}

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?uri WHERE { res:Aldi dbp:founder?uri }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri
WHERE {
 ?uri a dbo:Company ;
        dbo:industry dbr:Aerospace ;
        dbo:industry dbr:Medical
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?parent
WHERE {
  res:Queen_Victoria dbo:parent?parent
}

PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:>
ASK WHERE {?uri dct:subject dbc:Castles_in_the_United_States }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT * WHERE { res:Elizabeth_II dbo:father?uri.?uri dbo:gender "male"@en }

PREFIX dbc: <http://dbpedia.org/resource/Category:>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT DISTINCT?uri WHERE {{ dbc:Chemical_elements rdf:type dbc:Category ; rdfs:subClassOf owl:Thing.?uri rdfs:subClassOf dbc:Chemical_elements. }}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT DISTINCT?uri WHERE {
 ?uri rdf:type dbo:Person ;
       dct:subject dbc:Presidents_of_the_United_States ;
       dbp:birthDate?termEnd.
  FILTER ( year(now()) - year(?termEnd) <= 20 &&?termEnd < now() )
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT?n WHERE {?n dbo:wavelength "420-450"^^xsd:string }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT xsd:date(?year) WHERE { res:Jack_Wolfskin dbo:founder?year }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT xsd:date(?date) WHERE { {?date dbo:deathDate?s. FILTER (?s = res:Muhammad) } }

PREFIX res: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT DISTINCT?governor WHERE { res:Texas dbp:governor?governor }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT?uri
WHERE {
 ?uri a dbo:MilitaryConflict ;
       dbo:place dbr:San_Antonio ;
       dbo:date?date.
  FILTER (?date > "1835-12-31T00:00:00Z"^^xsd:dateTime )
  FILTER (?date <= "1836-12-10T00:00:00Z"^^xsd:dateTime ).
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?date WHERE { res:De_Beers dbo:foundingDate?date }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX res: <http://dbpedia.org/resource/>
SELECT DISTINCT?uri WHERE {
  res:Juan_Carlos_I_of_Spain dbo:spouse?x.
 ?x dbo:spouse?uri.
}

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
SELECT?Novelist WHERE {?Novel dbr:title "A Song of Ice and Fire" ; dbp:author?Novelist. }

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX db: <http://dbpedia.org/>
SELECT?studio WHERE {
 ?album dbo:artist dbr:The_Beatles ;
           rdf:type dbo:Album ;
           dbo:releaseDate?date ;
           dbp:recordedIn?studio.
} ORDER BY ASC(?date) LIMIT 1

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT?company WHERE {
 ?company dct:subject dbc:Companies_based_in_North_Rhine-Westphalia ;
    rdf:type dbo:Company.
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT (COUNT(DISTINCT?uri) AS?count)
WHERE {
  {{?uri dbo:country dbr:South_Carolina.
   ?uri rdf:type dbo:River.
  }
  UNION
  {
   ?uri dct:subject dbc:Rivers_of_South_Carolina.
  }
  UNION
  {
   ?uri dct:subject dbc:Lakes_of_South_Carolina.
  }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX dbc: <http://dbpedia.org/resource/Category:]
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT?uri WHERE {
 ?uri dct:subject dbc:States_of_the_United_States ;
    rdf:type dbo:AdministrativeRegion ;
    dbo:populationTotal?area.
  FILTER(?area > 0).
} ORDER BY DESC(?area) LIMIT 1
